DROP TABLE IF EXISTS `mdiy_tag`;
CREATE TABLE `mdiy_tag` (
                            `id` int NOT NULL AUTO_INCREMENT,
                            `tag_name` varchar(255) DEFAULT NULL COMMENT '标签名称',
                            `tag_type` varchar(255) DEFAULT NULL COMMENT '标签类型',
                            `tag_sql` text COMMENT '标签sql',
                            `tag_class` varchar(255) DEFAULT NULL COMMENT '标签类',
                            `tag_description` varchar(255) DEFAULT NULL COMMENT '描述',
                            `MODEL_ID` varchar(19) DEFAULT NULL COMMENT '模型id',
                            `UPDATE_BY` varchar(11) DEFAULT NULL COMMENT '更新人',
                            `UPDATE_DATE` datetime DEFAULT NULL COMMENT '更新时间',
                            `CREATE_BY` varchar(11) DEFAULT NULL COMMENT '创建人',
                            `CREATE_DATE` datetime DEFAULT NULL COMMENT '创建时间',
                            `APP_ID` varchar(20) DEFAULT 'global' COMMENT '站点id，如果是global说明在站群下是全局标识',
                            `DEL` int DEFAULT '0' COMMENT '删除标记',
                            `NOT_DEL` int DEFAULT '0' COMMENT '1为不能删除，主要用于系统默认数据,0为一般数据，主要是前端控制',
                            PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='标签';

-- ----------------------------
-- Records of mdiy_tag
-- ----------------------------
BEGIN;
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (3, 'arclist', 'list', '<#assign _typeid=\'\'/>\n<#assign _typetitle=\'\'/>\n<#-- 分页数，默认返回20条数据 -->\n<#assign _size=\'20\'/>\n<#if column?? && column.id?has_content>\n  <#assign  _typeid=\'column_id\'>\n  <#assign  _typeidvalue=\'${column.id}\'>\n</#if>\n<#if typeid??>\n  <#assign  _typeid=\'typeid\'>\n  <#assign  _typeidvalue=\'${typeid}\'>\n</#if>\n<#if typeids??>\n    <#assign  _typeids=\'${typeids}\'>\n</#if>\n<#if typetitle??>\n  <#assign  _typetitle=\'${typetitle}\'>\n</#if>\n<#if size??>\n  <#assign  _size=\'${size}\'>\n</#if>\n\n<#assign  _order=\'DESC\'>\n\n<#if !order?has_content>\n    <#assign order=\'DESC\'>\n</#if>\n\n<#assign  _orderby = \'\'>\n\n<#if orderby?has_content >\n    <#-- 将 orderBy 和 order 拆分为 list -->\n    <#assign fields = orderby?split(\',\')>\n    <#assign orders = order?split(\',\')>\n\n    <#-- 遍历所有字段 -->\n    <#list 0..(fields?size - 1) as i>\n        <#assign field = fields[i]?trim>\n        <#-- 如果字段为空则跳过 -->\n        <#if !field?has_content>\n            <#continue>\n        </#if>\n\n        <#-- 获取对应的排序方向，默认使用 default_order -->\n        <#if orders[i]?? && orders[i]?has_content>\n            <#assign direction = orders[i]?upper_case>\n            <#-- 合法性校验 -->\n            <#if direction != \'ASC\' && direction != \'DESC\'>\n                <#assign direction = _order>\n            </#if>\n        <#else>\n            <#assign direction = _order>\n        </#if>\n\n        <#assign ordercolumn = \'\'>\n        <#-- 映射字段 -->\n        <#if field == \'date\'>\n            <#assign ordercolumn = \'cms_content.content_datetime\'>\n        <#elseif field == \'updatedate\'>\n            <#assign ordercolumn = \'cms_content.update_date\'>\n        <#elseif field == \'hit\'>\n            <#assign ordercolumn = \'cms_content.content_hit\'>\n        <#elseif field == \'sort\'>\n            <#assign ordercolumn = \'cms_content.content_sort\'>\n        <#else>\n            <#-- 不支持的字段，跳过 -->\n            <#continue>\n        </#if>\n        <#-- 拼接到最终结果 -->\n        <#if _orderby?has_content>\n            <#assign _orderby += \',\'>\n        </#if>\n        <#assign _orderby += ordercolumn + \' \' + direction>\n    </#list>\n<#else>\n    <#assign _orderby = \'cms_content.content_datetime \' + _order>\n</#if>\n\n<#-- 优先使用搜索时的searchTableName变量，区分变量名避免文章模型被channel识别 -->\n<#if tableName??>\n    <#assign _tableName = tableName>\n<#elseif searchTableName??>\n    <#assign _tableName = searchTableName>\n</#if>\n\nSELECT\n    cms_content.id AS \"id\",\n    content_title AS \"title\",\n    content_short_title AS \"shorttitle\",\n    content_author AS \"author\",\n    content_source AS \"source\",\n    content_out_link AS \"outlink\",\n    content_tags AS \"tags\",\n\n    category.category_title AS \"typetitle\",\n    category.category_short_title AS \"typeshorttitle\",\n    category.id AS \"typeid\",\n    category.category_path AS \"typepath\",\n    category.category_img AS \"typelitpic\",\n    category.category_ico AS \"typeico\",\n    category.category_keyword as \"typekeyword\",\n    category.top_id as \"topid\",\n    category.category_id as \"parentid\",\n    category.category_parent_ids as \"parentids\",\n    category.category_type AS \"type\",\n        <#--列表页动态链接-->\n        <#if isDo?? && isDo>\n    CONCAT(\'${modelName}/list.do?style=${templateName!\"\"}&typeid=\', category.category_id) as \"typelink\",\n        <#else>\n        <#--栏目类型为链接-->\n        <#if shortSwitch?? && shortSwitch>\n    CONCAT(category.category_pinyin,\'.html\') AS \"typelink\",\n        <#else>\n    CONCAT(category.category_path,\'/index.html\') AS \"typelink\",\n        </#if>\n        </#if>\n    content_description AS \"descrip\",\n    content_hit AS \"hit\",\n    content_type AS \"flag\",\n    cms_content.content_keyword AS \"keyword\",\n    content_img AS \"litpic\",\n        <#--内容页动态链接-->\n        <#if isDo?? && isDo>\n        <#-- 保持 URL 结构的拼接 -->\n    CONCAT(\'${modelName}/view.do?style=${templateName!\"\"}&id=\', cms_content.id) as \"link\",\n        <#else>\n        <#if shortSwitch?? && shortSwitch>\n    CONCAT(CASE category_type WHEN \'2\' THEN category.category_pinyin ELSE cms_content.id END, \'.html\' ) as \"link\",\n        <#else>\n    CONCAT(CONCAT( category.category_path, \'/\' ), CONCAT(CASE category_type WHEN  \'2\' THEN \'index\' ELSE cms_content.id END , \'.html\' )) as \"link\",\n        </#if>\n        </#if>\n        <#if _tableName??>${_tableName}.*,</#if>\n    content_datetime AS \"date\"\nFROM\n    cms_content\n    LEFT JOIN\n    cms_category as category\nON cms_content.category_id = category.id\n    <#--判断是否有自定义模型表-->\n    <#if _tableName??>\n    LEFT JOIN ${_tableName} ON ${_tableName}.link_id=cms_content.id\n    </#if>\nWHERE\n    content_display=\'0\'\n  and category_display=\'enable\'\n  and cms_content.del=0\n\n    <#--文章审核-->\n    <#if contentApprove?? && contentApprove>\n  and cms_content.progress_status=\'终审通过\'\n    </#if>\n    <#--根据站点编号查询-->\n    <#if appId?? >\n  and cms_content.app_id = :appId\n    </#if>\n    <#--判断是否有搜索分类集合，暂时移除 _typeid=\"\" 条件-->\n    <#if search?? && !typeid??>\n  and category_is_search=\'enable\'\n    <#-- 文章标签 -->\n    <#if search.content_tag??>\n  and FIND_IN_SET(:search_content_tag, content_tags) > 0\n    </#if>\n    <#if search.categoryIds?has_content>\n    <#assign searchCategoryList = search.categoryIds?split(\",\")>\n  and (\n    <#list searchCategoryList as item>\n    <#if item?index gt 0>\n   or\n    </#if>\n    <#-- 使用循环索引作为参数后缀，支持单值与多值自适应 -->\n    (cms_content.category_id = <#if searchCategoryList?size == 1>:search_categoryIds<#else>:search_categoryIds_${item?index}</#if>\n   or cms_content.category_id in (select id FROM cms_category where cms_category.del=0\n    <#if _typetitle?has_content>\n  and cms_category.category_title = :_typetitle\n    </#if>\n  and FIND_IN_SET(<#if searchCategoryList?size == 1>:search_categoryIds<#else>:search_categoryIds_${item?index}</#if>, CATEGORY_PARENT_IDS) > 0)\n    )\n    </#list>\n    )\n    </#if>\n    <#--标题-->\n    <#if search.content_title??> and content_title like CONCAT(\'%\', :search_content_title, \'%\')</#if>\n    <#--作者-->\n    <#if search.content_author??> and content_author like CONCAT(\'%\', :search_content_author, \'%\')</#if>\n    <#--来源-->\n    <#if search.content_source??> and content_source like CONCAT(\'%\', :search_content_source, \'%\')</#if>\n    <#--属性-->\n    <#if search.content_type??>\n    <#assign searchContentTypeList = search.content_type?split(\',\')>\n  and(<#list searchContentTypeList as item>\n    <#if item?index gt 0> or</#if>\n    <#-- 使用循环索引 :search_content_type_n -->\n    FIND_IN_SET(<#if searchContentTypeList?size == 1>:search_content_type<#else>:search_content_type_${item?index}</#if>, cms_content.content_type) > 0\n    </#list>)\n    </#if>\n    <#--描述-->\n    <#if search.content_description??>\n  and content_description like CONCAT(\'%\', :search_content_description, \'%\')\n    </#if>\n    <#--关键字-->\n    <#if search.content_keyword??> and content_keyword like CONCAT(\'%\', :search_content_keyword, \'%\')</#if>\n    <#--内容-->\n    <#if search.content_details??> and content_details like CONCAT(\'%\', :search_content_details, \'%\')</#if>\n    <#--自定义顺序-->\n    <#if search.content_sort??> and content_sort = :search_content_sort</#if>\n    <#--时间范围-->\n    <#if search.content_datetime_start??&&search.content_datetime_end??>\n  and content_datetime between :search_content_datetime_start and :search_content_datetime_end\n    </#if>\n    <#else>\n    <#--查询栏目-->\n    <#if _typeids?has_content>\n    <#assign typeidsList = _typeids?split(\",\")>\n  and (\n    <#list typeidsList as item>\n    <#if item?index gt 0>\n   or\n    </#if>\n    <#-- 使用循环索引 :typeids_n -->\n    (cms_content.category_id = <#if typeidsList?size == 1>:typeids<#else>:typeids_${item?index}</#if>\n   or cms_content.category_id in (select id FROM cms_category where cms_category.del=0\n\n  and FIND_IN_SET(<#if typeidsList?size == 1>:typeids<#else>:typeids_${item?index}</#if>, CATEGORY_PARENT_IDS) > 0)\n    )\n    </#list>\n    )\n    <#elseif _typeidvalue?has_content && _typeidvalue?string != \'0\' >\n  and (cms_content.category_id = :${_typeid}\n   or cms_content.category_id in (select id FROM cms_category where cms_category.del=0\n  and FIND_IN_SET(:${_typeid}, CATEGORY_PARENT_IDS) > 0))\n    </#if>\n    </#if>\n    <#--判断搜索分类结束-->\n    <#--标题-->\n    <#if content_title??> and content_title like CONCAT(\'%\', :content_title, \'%\')</#if>\n    <#--作者-->\n    <#if content_author??> and content_author like CONCAT(\'%\', :content_author, \'%\')</#if>\n    <#--来源-->\n    <#if content_source??> and content_source like CONCAT(\'%\', :content_source, \'%\')</#if>\n    <#--属性-->\n    <#if content_type??> and content_type like CONCAT(\'%\', :content_type, \'%\')</#if>\n    <#--描述-->\n    <#if content_description??> and content_description like CONCAT(\'%\', :content_description, \'%\')</#if>\n    <#--关键字-->\n    <#if content_keyword??> and content_keyword like CONCAT(\'%\', :content_keyword, \'%\')</#if>\n    <#--内容-->\n    <#if content_details??> and content_details like CONCAT(\'%\', :content_details, \'%\')</#if>\n    <#--自定义顺序-->\n    <#if content_sort??> and content_sort = :content_sort</#if>\n    <#--自定义模型-->\n    <#if diyModel??>\n    <#list diyModel as key, value>\n    <#-- 生成占位符名称 -->\n    <#assign paramName = \"diyModel_\" + key>\n  and ${_tableName}.${key} like CONCAT(CONCAT(\'%\',:${paramName}),\'%\')\n    </#list>\n    </#if>\n    <#--文章属性-->\n    <#if flag?? >\n    <#assign flagList = flag?split(\',\')>\n  and(<#list flagList as item>\n    <#if item?index gt 0> or</#if>\n    <#-- 使用循环索引 :flag_n -->\n    FIND_IN_SET(<#if flagList?size == 1>:flag<#else>:flag_${item?index}</#if>, cms_content.content_type) > 0\n    </#list>)\n    </#if>\n    <#if noflag??>\n    <#assign noflagList = noflag?split(\',\')>\n  and(<#list noflagList as item>\n    <#if item?index gt 0> and</#if>\n    <#-- 使用循环索引 :noflag_n -->\n    FIND_IN_SET(<#if noflagList?size == 1>:noflag<#else>:noflag_${item?index}</#if>, cms_content.content_type)=0\n    </#list> or cms_content.content_type is null)\n    </#if>\n\n    <#--字段排序-->\nORDER BY\n        <#if topflag??>\n        <#assign topflagList = topflag?split(\",\")>\n    CASE\n        <#list topflagList as item>\n        <#-- 预编译参数 :topflag_n -->\n    WHEN FIND_IN_SET(<#if topflagList?size == 1>:topflag<#else>:topflag_${item?index}</#if>, cms_content.content_type) > 0 THEN ${item?index}\n        </#list>\n    ELSE 100\nEND,\n      </#if>\n${_orderby}\nLIMIT\n<#--判断是否分页-->\n<#if ispaging?? && (pageTag.pageNo)??>\n${((pageTag.pageNo-1)*_size?eval)?c},${_size?default(20)}\n<#else>\n${_size?default(20)}\n</#if>', NULL, '文章列表', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (4, 'channel', 'list', '<#assign _typeid=\'0\'/>\n<#if column?? && column.id?has_content>\n    <#assign  _typeid=\'column_id\'>\n</#if>\n\n<#if typeid?has_content>\n    <#assign  _typeid=\'typeid\'>\n</#if>\n<#if typeids??>\n    <#assign  _typeids=\'${typeids}\'>\n</#if>\n\n<#assign  _order=\'ASC\'>\n\n<#if !order?has_content>\n    <#assign order=\'ASC\'>\n</#if>\n\n\n<#assign  _orderby = \'\'>\n\n<#if orderby?has_content >\n    <#-- 将 orderBy 和 order 拆分为 list -->\n    <#assign fields = orderby?split(\',\')>\n    <#assign orders = order?split(\',\')>\n\n    <#-- 遍历所有字段 -->\n    <#list 0..(fields?size - 1) as i>\n        <#assign field = fields[i]?trim>\n        <#-- 如果字段为空则跳过 -->\n        <#if !field?has_content>\n            <#continue>\n        </#if>\n\n        <#-- 获取对应的排序方向，默认使用 default_order -->\n        <#if orders[i]?? && orders[i]?has_content>\n            <#assign direction = orders[i]?upper_case>\n            <#-- 合法性校验 -->\n            <#if direction != \'ASC\' && direction != \'DESC\'>\n                <#assign direction = _order>\n            </#if>\n        <#else>\n            <#assign direction = _order>\n        </#if>\n\n        <#assign ordercolumn = \'\'>\n        <#-- 映射字段 -->\n        <#if field == \'date\'>\n            <#assign ordercolumn = \'cms_category.create_date\'>\n        <#elseif field == \'sort\'>\n            <#assign ordercolumn = \'cms_category.category_sort\'>\n        <#else>\n            <#-- 不支持的字段，跳过 -->\n            <#continue>\n        </#if>\n        <#-- 拼接到最终结果 -->\n        <#if _orderby?has_content>\n            <#assign _orderby += \',\'>\n        </#if>\n        <#assign _orderby += ordercolumn + \' \' + direction>\n    </#list>\n     <#-- 容错处理，如果什么都没有匹配到，则默认按栏目id排序 -->\n    <#if !_orderby?has_content>\n        <#assign _orderby = \'cms_category.id \' + _order>\n    </#if>\n<#else>\n    <#assign _orderby = \'cms_category.id \' + _order>\n</#if>\n\n\n\nselect\n    cms_category.id as \"id\",\n    cms_category.id as \"typeid\",\n    cms_category.category_title as \"typetitle\",\n    cms_category.category_short_title as \"typeshorttitle\",\n        <#--动态链接-->\n        <#if isDo?? && isDo>\n    CASE WHEN cms_category.category_type= \'2\' THEN CONCAT(\'/${modelName}/view.do?style=${templateName!\"\"}&typeid=\', cms_category.id) ELSE CONCAT(\'/${modelName}/list.do?style=${templateName!\"\"}&typeid=\', cms_category.id) END as \"typelink\",\n    <#else>\n        <#--栏目类型为链接-->\n        <#if shortSwitch?? && shortSwitch>\n            CONCAT(cms_category.category_pinyin,\'.html\') AS \"typelink\",\n        <#else>\n            CONCAT(cms_category.category_path,\'/index.html\') as \"typelink\",\n        </#if>\n    </#if>\n    cms_category.category_keyword as \"typekeyword\",\n    cms_category.category_diy_url as \"typeurl\",\n    cms_category.category_flag as \"flag\",\n    cms_category.category_id as \"parentid\",\n    cms_category.category_parent_ids as \"parentids\",\n    cms_category.category_descrip as \"typedescrip\",\n    cms_category.category_type as \"type\",\n    cms_category.category_path as \"typepath\",\n    cms_category.leaf as \"typeleaf\",\n    cms_category.category_img as \"typelitpic\" ,\n    cms_category.category_ico as \"typeico\" ,\n    <#if tableName??>${tableName}.*,</#if>\n( SELECT count(*) FROM cms_category cc WHERE cc.category_id = cms_category.id AND cc.del = 0 ) AS \"childsize\"\nfrom\ncms_category\n<#--判断是否有自定义模型表-->\n<#if tableName??>LEFT JOIN ${tableName} ON ${tableName}.link_id=cms_category.id</#if>\nwhere\ncms_category.del=0\nand  cms_category.category_display = \'enable\'\nand  cms_category.is_child = \'cms\'\n<#--自定义模型-->\n<#if diyModel?? && tableName??>\n<#list diyModel as key, value>\n<#-- 生成占位符名称 -->\n<#assign paramName = \"diyModel_\" + key>\nand ${tableName}.${key} like CONCAT(CONCAT(\'%\',:${paramName}),\'%\')\n</#list>\n</#if>\n<#--根据站点编号查询-->\n<#if appId?? >\nand cms_category.app_id=:appId\n</#if>\n\n<#--栏目属性-->\n<#if flag?? >\n<#assign flagList = flag?split(\',\')>\nand\n(<#list flagList as item>\n<#if item?index gt 0> or</#if>\nFIND_IN_SET(<#if flagList?size == 1>:flag<#else>:flag_${item?index}</#if>,cms_category.category_flag)>0\n</#list>)\n</#if>\n\n<#if noflag?? && noflag?has_content>\n<#assign noflagList = noflag?split(\',\')>\nand (\n<#list noflagList as item>\n<#if item?index gt 0>and </#if>\nFIND_IN_SET(\n<#if noflagList?size == 1>:noflag<#else>:noflag_${item?index}</#if>,\ncms_category.category_flag\n) = 0\n</#list>\nor cms_category.category_flag is null)\n</#if>\n\n<#--type默认son-->\n<#if !type??||!type?has_content>\n<#assign type=\'son\'/>\n</#if>\n\n<#-- 如果有typeids参数，则只查询typeids参数指定的栏目  -->\n<#if _typeids?has_content>\nand cms_category.id in (:typeids) <#-- 预编译处理，后端需传入List -->\n<#elseif type?has_content>\n<#--顶级栏目（单个）-->\n<#if type==\'top\'>\n<#if _typeid != \'0\'>\nand (cms_category.id = cms_category.top_id or cms_category.top_id = \'0\')\n</#if>\n\n<#elseif type==\'nav\'>\nand(cms_category.category_id is null)\n\n<#--同级栏目（多个）-->\n<#elseif type==\'level\'>\n<#if _typeid != \'0\'>\nand cms_category.category_id=(select category_id from cms_category where id=:${_typeid})\n</#if>\n\n<#--当前栏目或指定栏目（单个）-->\n<#elseif type==\'self\'>\n<#if _typeid != \'0\'>\nand cms_category.id=:${_typeid}\n</#if>\n\n\n<#--当前栏目的所属栏目（多个）-->\n<#elseif type==\'path\'>\n<#if _typeid != \'0\'>\nand cms_category.id in\n(<#if column?? && column.categoryParentIds??>\n<#assign parentIdsList = column.categoryParentIds?split(\',\')>\n<#list parentIdsList as parentId>\n<#if parentIdsList?size == 1>:column_categoryParentIds<#else>:column_categoryParentIds_${parentId?index}</#if>,\n</#list>\n</#if>:${_typeid})\n</#if>\n\n<#--子栏目（多个）-->\n<#elseif type==\'son\'>\n<#if _typeid != \'0\'>\nand cms_category.category_id=:${_typeid}\n</#if>\n\n<#--上一级栏目没有则取当前栏目（单个）-->\n<#elseif type==\'parent\'>\nand\n<#if typeid?has_content>\ncms_category.id=(select category_id from cms_category where id=:${_typeid})\n<#else>\ncms_category.id=:column_categoryId\n</#if>\n</#if>\n\n<#else> <#--默认顶级栏目-->\nand\n<#if _typeid != \'0\'>\ncms_category.id=:${_typeid}\n<#else>\n(cms_category.category_id is null)\n</#if>\n</#if>\n\n<#--字段排序-->\n<#if type == \'path\'>\nORDER BY cms_category.category_path asc\n<#else>\n\nORDER BY  ${_orderby}\n\n</#if>\n<#if size??>\nLIMIT ${size}\n</#if>', NULL, '通用栏目', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (5, 'global', 'single', 'select\n  APP_NAME as \"name\",\n  app_logo as \"logo\",\n  app_ico as \"ico\",\n  app_keyword as \"keyword\",\n  app_description as \"descrip\",\n  app_copyright as \"copyright\",\n  \'${contextPath}\' as \"contextpath\",\n  <#--动态解析 -->\n  <#if isDo?? && isDo>\n    \'${url}\' as \"url\",\n    \'${url}\' as \"host\",\n    \'/\' as \"html\",\n  <#--使用地址栏的域名 -->\n  <#else>\n    <#if shortSwitch?? && shortSwitch>\n      CONCAT(\'${url}\',\'${appDir}<#if appDir?has_content>/</#if>\') as \"url\",\n      \'<#if appDir?has_content>/</#if>${appDir}/\' as \"html\",\n    <#else>\n      CONCAT(CONCAT(\'${url}\',\'${html}/\'),\'<#if appDir?has_content>${appDir}/</#if>\') as \"url\",\n      CONCAT(CONCAT(\'/${html}\',\'<#if appDir?has_content>/${appDir}</#if>\'),\'/\') as \"html\",\n    </#if>\n    \'${url}\' as \"host\",\n  </#if>\n    CONCAT(CONCAT(CONCAT(CONCAT(\'${template}/\',id),\'/\'),app_style),\'/\') as \"style\"\nfrom app\n  <#--根据站点编号查询-->\n  <#if appId?? >\n    where id = :appId\n  </#if>', NULL, '全局', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (7, 'field', 'single', 'SELECT\n    cms_content.id as \"id\",\n    <#--这里会存在id覆盖的情况,所以需要在cms_content.id下面-->\n    <#if tableName??>${tableName}.*,</#if>\n    <#--查询站点编号-->\n    <#if appId??>\n        cms_content.app_id as \"appId\",\n    </#if>\n    content_title as \"title\",\n    content_short_title AS \"shorttitle\",\n    content_author as \"author\",\n    content_source as \"source\",\n    content_out_link as \"outlink\",\n    content_details as \"content\",\n    content_datetime as \"date\",\n    content_description as \"descrip\",\n    content_keyword as \"keyword\",\n    <#if contextPath?? && contextPath != \"/\">\n    	CONCAT(CONCAT( \'<script type=\"text/javascript\" src=\"${contextPath}/cms/content/\', cms_content.id),\'/hit.do\"></script>\') as \"hit\",\n    <#else>\n    	CONCAT(CONCAT( \'<script type=\"text/javascript\" src=\"/cms/content/\', cms_content.id),\'/hit.do\"></script>\') as \"hit\",\n    </#if>\n    content_type as \"flag\",\n    content_tags as \"tags\",\n    category_title as \"typetitle\",\n    cms_content.content_img as \"litpic\",\n    <#if shortSwitch?? && shortSwitch>\n        <#if dateSwitch?? && dateSwitch>\n            CONCAT(CONCAT(CONCAT(DATE_FORMAT(cms_content.create_date, \'%Y%m%d\'),cms_content.id),\'.html\') AS \"link\",\n        <#else>\n            CONCAT(cms_content.id,\'.html\') AS \"link\",\n        </#if>\n    <#else>\n        <#if dateSwitch?? && dateSwitch>\n            CONCAT(CONCAT( cms_category.category_path, \'/\' ), CONCAT(CONCAT(CONCAT(DATE_FORMAT(cms_content.create_date, \'%Y%m%d\'),cms_content.id), \'.html\' )) as \"link\",\n        <#else>\n            CONCAT(CONCAT( cms_category.category_path, \'/\' ), CONCAT(cms_content.id, \'.html\' )) as \"link\",\n        </#if>\n    </#if>\n    cms_category.id as \"typeid\",\n    cms_category.leaf as \"typeleaf\",\n    cms_category.category_title as \"typetitle\",\n    cms_category.category_short_title AS \"typeshorttitle\",\n    cms_category.category_img as \"typelitpic\",\n    cms_category.category_ico as \"typeico\",\n    cms_category.category_path as \"typepath\",\n    cms_category.top_id as \"topid\",\n    cms_category.category_flag as \"typeflag\",\n    cms_category.category_id as \"parentid\",\n    cms_category.category_parent_ids as \"parentids\",\n    cms_category.category_keyword as \"typekeyword\",\n    cms_category.category_descrip as \"typedescrip\",\n    <#if shortSwitch?? && shortSwitch>\n        CONCAT(category_pinyin,\'.html\') AS \"typelink\"\n    <#else>\n        CONCAT(category_path,\'/index.html\') AS \"typelink\"\n    </#if>\n\nFROM cms_content\n    LEFT JOIN cms_category  ON\n    cms_category.id = cms_content.category_id\n    <#--判断是否有自定义模型表-->\n    <#if tableName??>left join ${tableName} on ${tableName}.link_id=cms_content.id</#if>\nWHERE\n    <#--如果是栏目列表页没有文章id所以只取栏目id-->\n    <#if column??&&column.id??&&!id??>\n        cms_category.id=:column_id and\n    </#if>\n    <#--根据站点编号查询-->\n    <#if appId??>\n        cms_content.app_id = :appId and\n    </#if>\n    cms_content.del=0\n    <#if id??> and cms_content.id=:id</#if>\n', NULL, '文章内容', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (8, 'pre', 'single', '<#assign select=\"\'\'\"/>\n<#if orderby?? >\n	<#if orderby==\"date\">\n	  <#assign  _orderby=\"content_datetime\">\n	<#elseif orderby==\"updatedate\">\n	  <#assign  _orderby=\"cms_content.update_date\">\n	<#elseif orderby==\"hit\">\n	  <#assign  _orderby=\"content_hit\">\n	<#elseif orderby==\"sort\">\n	  <#assign  _orderby=\"content_sort\">\n	<#else><#assign  _orderby=\"cms_content.id\"></#if>\n<#else>\n	<#assign  _orderby=\"cms_content.id\">\n</#if>\n<#--上一页-->\n<#if pageTag.preId??>\n	SELECT\n    cms_content.id as \"id\",\n    content_title as \"title\",\n    content_author as \"author\",\n    content_source as \"source\",\n    content_details as \"content\",\n    content_out_link AS \"outlink\",\n    category.category_title as \"typename\",\n    category.category_id as \"typeid\",\n    <#if shortSwitch?? && shortSwitch>\n        CONCAT(category.category_pinyin,\'.html\') AS \"typelink\",\n    <#else>\n        CONCAT(category.category_path,\'/index.html\') AS \"typelink\",\n    </#if>\n    content_img as \"litpic\",\n    <#--内容页动态链接-->\n    <#if shortSwitch?? && shortSwitch>\n        CONCAT(cms_content.id,\'.html\') AS \"link\",\n    <#else>\n        CONCAT(CONCAT(category_path,\'/\'),CONCAT(cms_content.id,\'.html\')) AS \"link\",\n    </#if>\n    content_description as \"descrip\",\n    content_hit as \"hit\",\n    content_type as \"flag\",\n    content_keyword as \"keyword\"\n	FROM cms_content\n    LEFT JOIN cms_category category ON cms_content.category_id=category.id\n	WHERE cms_content.id=:pageTag_preId\n<#else>\n	SELECT\n    ${select} as \"id\",\n    \'没有了\' as \"title\",\n    ${select} as \"author\",\n    ${select} as \"source\",\n    ${select} as \"content\",\n    ${select} as \"typename\",\n    ${select} as \"typeid\",\n    ${select} as \"typelink\",\n    ${select} as \"litpic\",\n    ${select} as \"typelink\",\n    ${select} as \"date\",\n    ${select} as \"descrip\",\n    ${select} as \"hit\",\n    ${select} as \"flag\",\n    ${select} as \"keyword\",\n	${select} as \"outlink\"\n    FROM dual\n</#if>\n', NULL, '文章上一篇', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (9, 'page', 'single', '<#if pageTag??>\nselect\n  <#--是否开启短链接-->\n    <#if shortSwitch?? && shortSwitch>\n	    \'${shortSwitch?string(\'true\',\'false\')}\' as \"shortSwitch\",\n    </#if>\n	<#if !(pageTag.indexUrl??)>\n		<#--判断是否有栏目对象，用于搜索不传栏目-->\n        <#-- 处理动态访问问题 -->\n        <#if isDo?? && isDo>\n            <#assign path=\'/${modelName}/list.do?style=${templateName!\"\"}&typeid=${column.id}\'/>\n		<#elseif column??>\n			<#if shortSwitch?? && shortSwitch>\n				<#assign path=column.categoryPinyin/>\n			<#else>\n				<#assign path=column.categoryPath/>\n			</#if>\n		<#else>\n			<#assign path=\'\' />\n		</#if>\n		<#--总记录数、总页数-->\n		\'${pageTag.total}\' as \"total\",\n		\'${pageTag.size}\' as \"size\",\n\n		<#--记录总数-->\n		\'${pageTag.rcount}\' as \"rcount\",\n		<#--当前页码-->\n		\'${pageTag.pageNo}\' as \"cur\",\n		<#--首页-->\n        <#if isDo?? && isDo>\n            \'${path}\' as \"index\",\n		<#elseif shortSwitch?? && shortSwitch>\n			CONCAT(\'${path}\', \'.html\') as \"index\",\n		<#else>\n			CONCAT(\'${path}\', \'/index.html\') as \"index\",\n		</#if>\n		<#--上一页-->\n		<#if (pageTag.pageNo?eval-1) gt 1>\n            <#if isDo?? && isDo>\n                CONCAT(\'${path}\',\'&pageNo=${pageTag.pageNo?eval-1}\') as \"pre\",\n			<#elseif shortSwitch?? && shortSwitch>\n				CONCAT(\'${path}\',\'-${pageTag.pageNo?eval-1}.html\') as \"pre\",\n			<#else>\n				CONCAT(\'${path}\',\'/list-${pageTag.pageNo?eval-1}.html\') as \"pre\",\n			</#if>\n		<#else>\n            <#if isDo?? && isDo>\n                \'${path}\' as \"pre\",\n			<#elseif shortSwitch?? && shortSwitch>\n				CONCAT(\'${path}\',\'.html\') as \"pre\",\n			<#else>\n				CONCAT(\'${path}\',\'/index.html\') as \"pre\",\n			</#if>\n		</#if>\n		<#--下一页-->\n		<#if pageTag.total lte 1>\n            <#--处理动态访问情况-->\n            <#if isDo?? && isDo>\n                \'${path}\' as \"next\",\n                \'${path}\' as \"last\"\n			<#elseif shortSwitch?? && shortSwitch>\n				CONCAT(\'${path}\', \'.html\') as \"next\",\n				CONCAT(\'${path}\', \'.html\') as \"last\"\n			<#else>\n				CONCAT(\'${path}\', \'/index.html\') as \"next\",\n				CONCAT(\'${path}\', \'/index.html\') as \"last\"\n			</#if>\n		<#else>\n			<#if pageTag.pageNo?eval gte pageTag.total>\n                <#if isDo?? && isDo>\n                    CONCAT(\'${path}\',\'&pageNo=${pageTag.total}\') as \"next\",\n				<#elseif shortSwitch?? && shortSwitch>\n					CONCAT(\'${path}\',\'-${pageTag.total}.html\') as \"next\",\n				<#else>\n					CONCAT(\'${path}\',\'/list-${pageTag.total}.html\') as \"next\",\n				</#if>\n			<#else>\n                <#if isDo?? && isDo>\n                    CONCAT(\'${path}\',\'&pageNo=${pageTag.pageNo?eval+1}\') as \"next\",\n				<#elseif shortSwitch?? && shortSwitch>\n					CONCAT(\'${path}\',\'-${pageTag.pageNo?eval+1}.html\') as \"next\",\n				<#else>\n					CONCAT(\'${path}\',\'/list-${pageTag.pageNo?eval+1}.html\') as \"next\",\n				</#if>\n			</#if>\n			<#--最后一页-->\n            <#if isDo?? && isDo>\n                CONCAT(\'${path}\',\'&pageNo=${pageTag.total}\') as \"last\"\n			<#elseif shortSwitch?? && shortSwitch>\n				CONCAT(\'${path}\',\'-${pageTag.total}.html\') as \"last\"\n			<#else>\n				CONCAT(\'${path}\',\'/list-${pageTag.total}.html\') as \"last\"\n			</#if>\n		</#if>\n	<#else>\n		<#--判断是否是搜索页面-->\n		\'${pageTag.indexUrl}\' as \"index\",\n		\'${pageTag.lastUrl}\' as \"last\",\n		\'${pageTag.preUrl}\' as \"pre\",\n		\'${pageTag.nextUrl}\' as \"next\",\n		\'${pageTag.total}\' as \"total\",\n		\'${pageTag.size}\' as \"size\",\n		\'${pageTag.rcount}\' as \"rcount\",\n		\'${pageTag.pageNo}\' as \"cur\"\n	</#if>\n    from dual\n</#if>', NULL, '通用分页', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (10, 'next', 'single', '<#assign select=\"\'\'\"/>\n<#if orderby?? >\n	<#if orderby==\"date\">\n		<#assign  _orderby=\"content_datetime\">\n	<#elseif orderby==\"updatedate\">\n		<#assign  _orderby=\"cms_content.update_date\">\n	<#elseif orderby==\"hit\">\n		<#assign  _orderby=\"content_hit\">\n	<#elseif orderby==\"sort\">\n		<#assign  _orderby=\"content_sort\">\n	<#else>\n		<#assign  _orderby=\"cms_content.id\">\n    </#if>\n<#else>\n    <#assign  _orderby=\"cms_content.id\">\n</#if>\n<#--开始-->\n<#if pageTag.nextId??>\n	SELECT\n    cms_content.id as \"id\",\n    content_title as \"title\",\n    content_author as \"author\",\n    content_source as \"source\",\n    content_details as \"content\",\n	content_out_link as \"outlink\",\n    category.category_title as \"typename\",\n    category.category_id as \"typeid\",\n    <#if shortSwitch?? && shortSwitch>\n        CONCAT(category.category_pinyin,\'.html\') AS \"typelink\",\n    <#else>\n        CONCAT(category.category_path,\'/index.html\') AS \"typelink\",\n    </#if>\n    content_img as \"litpic\",\n    <#--内容页动态链接-->\n    <#if shortSwitch?? && shortSwitch>\n        CONCAT(cms_content.id,\'.html\') AS \"link\",\n    <#else>\n        CONCAT(CONCAT(category_path,\'/\'),CONCAT(cms_content.id,\'.html\')) AS \"link\",\n    </#if>\n    content_description as \"descrip\",\n    content_hit as \"hit\",\n    content_type as \"flag\",\n    content_keyword as \"keyword\"\n	FROM cms_content\n    LEFT JOIN cms_category category ON cms_content.category_id=category.id\n	WHERE cms_content.id=:pageTag_nextId\n<#else>\n  SELECT\n    ${select} as \"id\",\n    \'没有了\' as \"title\",\n    ${select} as \"author\",\n    ${select} as \"source\",\n    ${select} as \"content\",\n    ${select} as \"typename\",\n    ${select} as \"typeid\",\n    ${select} as \"typelink\",\n    ${select} as \"litpic\",\n    ${select} as \"link\",\n    ${select} as \"date\",\n    ${select} as \"descrip\",\n    ${select} as \"hit\",\n    ${select} as \"flag\",\n    ${select} as \"keyword\",\n	${select} as \"outlink\"\n  FROM dual\n</#if>\n', NULL, '文章下一篇', NULL, NULL, NULL, NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (11, 'diyform', 'macro', '<#macro ms_diyform formName>\n<div id=\"form\" v-cloak style=\"width: 30%; margin: 5% auto\">\n  <div id=\"formModel\">\n    <!--会自动渲染代码生成器的表单-->\n  </div>\n  <!--必须包含验证码-->\n  <el-form ref=\"form\" :model=\"form\" :rules=\"rules\" label-position=\"right\" size=\"large\" label-width=\"120px\">\n    <el-row :gutter=\"0\" justify=\"start\" align=\"top\">\n      <el-col :span=\"12\">\n        <el-form-item label=\"验证码\" prop=\"rand_code\">\n          <el-input\n                  v-model=\"form.rand_code\"\n                  :disabled=\"false\"\n                  :readonly=\"false\"\n                  :clearable=\"true\"\n                  placeholder=\"请输入验证码\">\n          </el-input>\n        </el-form-item>\n      </el-col>\n      <el-col :span=\"12\">\n        <div style=\"display: flex; height: 38px;margin-left: 1em; align-items: center; cursor: pointer\">\n          <img :src=\"verifCode\" class=\"code-img\" @click=\"code\"/>\n          <div @click=\"code\" style=\"margin-left: 10px\">\n            看不清？换一张\n          </div>\n        </div>\n      </el-col>\n    </el-row>\n    <el-form-item label=\"  \">\n      <el-button @click=\"save\" type=\"primary\" :loading=\"isLoading\" style=\"width: 200px\">\n        {{isLoading ? \'保存中\' : \'保存\'}}\n      </el-button>\n    </el-form-item>\n  </el-form>\n</div>\n<script>\n  //vue的实例名称必须为 from\n  var form = new Vue({\n    el: \'#form\',\n    data: {\n      formModel: undefined, //自定义业务的vue对象\n      verifCode:  \"/code.do?t=\" + new Date().getTime(),\n      isLoading: false,\n      form: {\n        rand_code: \'\'\n      },\n      rules: {\n        rand_code: [\n          {required: true, message: \'请输入验证码\', trigger: \'blur\'},\n          {min: 1, max: 4, message: \'长度不能超过4个字符\', trigger: \'change\'}\n        ],\n      },\n    },\n    methods: {\n      save: function () {\n        var that = this;\n        that.isLoading = true;\n        //将验证码值复制到自定义模型\n        form.formModel.form.rand_code = this.form.rand_code;\n        //调用自定义模型的保存\n        that.formModel.save(function (res) {\n          if (res.result) {\n            that.$notify({\n              title: \'成功\',\n              type: \'success\',\n              message: \'保存成功!\'\n            });\n\n          } else {\n            that.$notify({\n              title: \'失败\',\n              message: res.msg,\n              type: \'warning\'\n            });\n          }\n          that.isLoading = false;\n        });\n      },\n      code: function () {\n        this.verifCode = \"/code.do?t=\" + (new Date).getTime();\n      }\n    },\n    created: function () {\n      var that = this;\n      ms.mdiy.model.form(\"formModel\", { \"modelName\": \"${formName}\" }).then(function(obj) {\n        that.formModel = obj;\n      });\n    }\n  });\n</script>\n</#macro>', NULL, '智能表单', NULL, '57', '2022-11-15 16:10:49', NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (12, 'data', 'list', 'SELECT\n	cms_content.id AS \"id\",\n	content_title AS \"title\",\n	content_author AS \"author\",\n	content_source AS \"source\",\n	content_details AS \"content\",\n	content_out_link AS \"outlink\",\n	content_short_title AS \"shorttitle\",\n	category.category_title AS \"typetitle\",\n	category.category_short_title AS \"typeshorttitle\",\n	category.id AS \"typeid\",\n	category.category_path AS \"typepath\",\n	category.category_img AS \"typelitpic\",\n	category.category_ico AS \"typeico\",\n	category.category_keyword AS \"typekeyword\",\n	category.top_id AS \"topid\",\n	category.category_parent_ids AS \"parentids\",\n	category.category_type AS \"type\",\n	<#--列表页动态链接-->\n	<#if isDo?? && isDo>\n	    CONCAT(\'/${modelName}/list.do?style=${templateName!\"\"}&typeid=\', category.category_id) AS \"typelink\",\n	<#else>\n	<#if shortSwitch?? && shortSwitch>\n		CONCAT(category_pinyin,\'.html\') AS \"typelink\",\n	<#else>\n		CONCAT(category_path,\'/index.html\') AS \"typelink\",\n	</#if>\n	</#if>\n	content_description AS \"descrip\",\n	content_hit AS \"hit\",\n	content_type AS \"flag\",\n	cms_content.content_keyword AS \"keyword\",\n	content_img AS \"litpic\",\n	<#--内容页动态链接-->\n	<#if isDo?? && isDo>\n		CONCAT(\'/${modelName}/view.do?style=${templateName!\"\"}&id=\', cms_content.id) AS \"link\",\n	<#else>\n		<#if shortSwitch?? && shortSwitch>\n			CONCAT(cms_content.id,\'.html\') AS \"link\",\n		<#else>\n			CONCAT(CONCAT(CONCAT(category.category_path,\'/\'),cms_content.id),\'.html\') AS \"link\",\n		</#if>\n	</#if>\n 	<#if tableName??>${tableName}.*,</#if>\n	content_datetime AS \"date\"\nFROM\n	cms_content LEFT JOIN cms_category category ON cms_content.category_id = category.id\n	<#--判断是否有自定义模型表-->\n	<#if tableName??>\n		LEFT JOIN ${tableName} ON ${tableName}.link_id=cms_content.id\n	</#if>\nWHERE\n  content_display=\'0\'\n  and category_display=\'enable\'\n  and cms_content.del=0\n	<#--根据站点编号查询-->\n	<#if appId?? >\n		and cms_content.app_id=:appId\n	</#if>\n	and cms_content.id=:dataid', NULL, '单篇', NULL, '57', '2022-11-15 16:10:49', NULL, NULL, 'global', 0, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (17, 'tag', 'single', '<#assign _typeid=\'0\'/>\n<#assign order=\'desc\'/>\n<#assign _size=\'99\'/>\n<#if column?? && column.id?has_content>\n  <#assign  _typeid=\'column_id\'>\n</#if>\n\n<#if typeid??>\n  <#assign  _typeid=\'typeid\'>\n</#if>\n<#if size??>\n  <#assign  _size=\'${size}\'>\n</#if>\n\nSELECT\n    GROUP_CONCAT(DISTINCT content_tags ) AS tags\nFROM\n    cms_content\nLEFT JOIN cms_category ON cms_content.category_id = cms_category.id\nWHERE\n  cms_category.category_display = \'enable\'\n  AND cms_content.del = 0\n  AND cms_content.content_display = \'0\'\n  AND LENGTH( cms_content.content_tags )>0\n    <#if _typeid != \'0\'>\n      AND (cms_category.id = :${_typeid} or FIND_IN_SET(:${_typeid},cms_category.category_parent_ids) > 0)\n    </#if>\n    <#if appId??>\n  AND cms_content.app_id = :appId\n    </#if>\nORDER BY CONTENT_HIT DESC\nLimit ${_size}', '', '文章标签配置，不提供模板使用', NULL, '', '2023-06-12 17:26:19', '57', '2023-05-23 09:31:49', 'global', 57, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (18, 'tags', 'macro', '<#assign tags=\"\">\n<#macro ms_tags>\n    <#if tag??>\n        <#assign ___tags = tag.tags?split(\",\")>\n		<#list ___tags as tag>\n		    <#list ___tags as _tag>\n		        <#if tag == _tag>\n		            <#if tag_index == _tag_index>\n		            	<#assign tags+=tag+\",\">\n		            <#else>\n		            <#break>\n		            </#if>\n		        </#if>\n		    </#list>\n		</#list>\n    </#if>\n</#macro>', '', '文章标签', NULL, '', '2023-06-12 17:26:21', '57', '2023-05-23 09:31:40', 'global', 57, 1);
INSERT INTO `mdiy_tag` (`id`, `tag_name`, `tag_type`, `tag_sql`, `tag_class`, `tag_description`, `MODEL_ID`, `UPDATE_BY`, `UPDATE_DATE`, `CREATE_BY`, `CREATE_DATE`, `APP_ID`, `DEL`, `NOT_DEL`) VALUES (20, 'pageurl', 'macro', '<#macro ms_pageurl>\n<script>\n    //当前列表路径，方便第三方插件调用\n    function pageurl(val) {\n        <#if shortSwitch?? && shortSwitch>\n		    var basePath = \"${global.html}${field.categoryPinyin}\";\n            // 短链接方式\n            if (val == 1) {\n                return basePath + \".html\";\n            } else {\n                return basePath + \"-\" + val + \".html\";\n            }\n        <#else>\n			var basePath = \"${global.html}${field.categoryPath}\";\n            // 普通分页方式\n            if (val == 1) {\n                return basePath + \"/index.html\";\n            } else {\n                return basePath + \"/list-\" + val + \".html\";\n            }\n        </#if>\n    }\n</script>\n</#macro>', NULL, '分页连接', NULL, NULL, '2026-04-03 14:49:03', '57', '2026-04-03 14:49:03', 'global', 0, 0);
COMMIT;

INSERT INTO `mdiy_model` (`ID`, `model_json`, `model_table_name`, `model_name`, `model_id_type`, `model_type`, `model_field`, `model_custom_type`, `update_date`, `update_by`, `create_date`, `create_by`, `del`, `NOT_DEL`, `APP_ID`) VALUES (2034199378837450753, '{\"searchJson\":\"[\\n    {\\n    \\\"isSearch\\\": \\\"\\\",\\n    \\\"action\\\": \\\"and\\\",\\n    \\\"field\\\": \\\"API_KEY\\\",\\n    \\\"el\\\": \\\"eq\\\",\\n    \\\"model\\\": \\\"apiKey\\\",\\n    \\\"name\\\": \\\"ApiKey\\\",\\n    \\\"type\\\": \\\"input\\\"\\n    },\\n    {\\n    \\\"action\\\": \\\"and\\\",\\n    \\\"field\\\": \\\"API_KEY_SWITCH\\\",\\n    \\\"el\\\": \\\"eq\\\",\\n    \\\"model\\\": \\\"apiKeySwitch\\\",\\n    \\\"name\\\": \\\"启用ApiKey\\\",\\n    \\\"type\\\": \\\"switch\\\"\\n    },\\n]\\n\",\"isWebCode\":false,\"form\":\"[{\\\"type\\\":\\\"input\\\",\\\"name\\\":\\\"ApiKey\\\",\\\"icon\\\":\\\"icon-danhangwenben\\\",\\\"pmofAllowUpdate\\\":1,\\\"pmofAllowGenerater\\\":1,\\\"pmofAllowRepet\\\":1,\\\"pmofAllowValidator\\\":1,\\\"pmofAllowEmpty\\\":1,\\\"pmofLength\\\":255,\\\"pmofType\\\":\\\"VARCHAR\\\",\\\"pmofJavaType\\\":\\\"String\\\",\\\"pmofSort\\\":0,\\\"likeSearch\\\":true,\\\"help\\\":\\\"填写<a  target=\\\\\\\"_blank\\\\\\\" href=\\\\\\\"https://console.mingsoft.net/#/keyList\\\\\\\" >会员中心</a>生成ApiKey\\\",\\\"options\\\":{\\\"isShow\\\":true,\\\"isFk\\\":false,\\\"readonly\\\":false,\\\"width\\\":\\\"100%\\\",\\\"isNoRepeat\\\":false,\\\"defaultValue\\\":\\\"\\\",\\\"clearable\\\":true,\\\"isLength\\\":true,\\\"lengthConfig\\\":{\\\"min\\\":32,\\\"max\\\":32},\\\"required\\\":true,\\\"dataType\\\":\\\"string\\\",\\\"isPattern\\\":false,\\\"isDataType\\\":false,\\\"pattern\\\":\\\"\\\",\\\"placeholder\\\":\\\"请输入ApiKey\\\",\\\"disabled\\\":false,\\\"table\\\":{\\\"search\\\":false,\\\"show\\\":true,\\\"align\\\":\\\"left\\\"}},\\\"key\\\":\\\"INPUT_BKBZR\\\",\\\"model\\\":\\\"API_KEY\\\",\\\"rules\\\":\\\"[{\\\\\\\"required\\\\\\\":true,\\\\\\\"message\\\\\\\":\\\\\\\"ApiKey不能为空\\\\\\\"},{\\\\\\\"min\\\\\\\":32,\\\\\\\"max\\\\\\\":32,\\\\\\\"message\\\\\\\":\\\\\\\"ApiKey长度必须为32-32\\\\\\\"}]\\\"},{\\\"type\\\":\\\"switch\\\",\\\"name\\\":\\\"启用ApiKey\\\",\\\"icon\\\":\\\"icon-kaiguan1\\\",\\\"pmofAllowUpdate\\\":1,\\\"pmofAllowGenerater\\\":1,\\\"pmofAllowRepet\\\":1,\\\"pmofAllowValidator\\\":1,\\\"pmofAllowEmpty\\\":1,\\\"pmofLength\\\":255,\\\"pmofType\\\":\\\"VARCHAR\\\",\\\"pmofJavaType\\\":\\\"Boolean\\\",\\\"pmofSort\\\":0,\\\"likeSearch\\\":false,\\\"help\\\":\\\"如果不使用，请务必将其关闭\\\",\\\"options\\\":{\\\"isShow\\\":true,\\\"defaultValue\\\":false,\\\"disabled\\\":false,\\\"table\\\":{\\\"search\\\":false,\\\"show\\\":false,\\\"align\\\":\\\"left\\\"}},\\\"key\\\":\\\"SWITCH_CRCBT\\\",\\\"model\\\":\\\"API_KEY_SWITCH\\\"}]\",\"isWebSubmit\":false,\"html\":\"\\n<template id=\\\"custom-model\\\">\\n    <el-form ref=\\\"form\\\" :model=\\\"form\\\" :rules=\\\"rules\\\" label-width=\\\"120px\\\" label-position=\\\"right\\\" size=\\\"default\\\" :disabled=\\\"disabled\\\" v-loading=\\\"loading\\\">\\n            <!--ApiKey-->\\n\\n\\t        <el-form-item  label=\\\"ApiKey\\\" prop=\\\"apiKey\\\">\\n\\t            <el-input\\n                        v-model=\\\"form.apiKey\\\"\\n                         :disabled=\\\"false\\\"\\n                          :readonly=\\\"false\\\"\\n                          :style=\\\"{width:  \'100%\'}\\\"\\n                          :clearable=\\\"true\\\"\\n                        placeholder=\\\"请输入ApiKey\\\">\\n                </el-input>\\n                <div class=\\\"ms-form-tip\\\">\\n填写<a target=\\\"_blank\\\" href=\\\"https://console.mingsoft.net/#/keyList\\\" >会员中心</a>生成ApiKey                </div>\\n\\t        </el-form-item>   \\n        <!--启用ApiKey-->\\n    \\n        <el-form-item  label=\\\"启用ApiKey\\\" prop=\\\"apiKeySwitch\\\">\\n            <el-switch v-model=\\\"form.apiKeySwitch\\\"\\n                       :disabled=\\\"false\\\">\\n            </el-switch>\\n                <div class=\\\"ms-form-tip\\\">\\n如果不使用，请务必将其关闭                </div>\\n        </el-form-item>\\n   \\n    </el-form>\\n</template>\\n\",\"id\":0,\"script\":\"var custom_model = Vue.component(\\\"custom-model\\\",{\\n    el: \'#custom-model\',\\n    data:function() {\\n        return {\\n\\t\\t\\tloading:false,\\n            disabled:false,\\n            modelId:0,\\n            modelName: \\\"APIKey配置\\\",\\n            //表单数据\\n            form: {\\n                linkId:0,\\n                    // ApiKey\\n                    apiKey:\'\',\\n                    // 启用ApiKey\\n                    apiKeySwitch:false,\\n            },\\n\\n            rules:{\\n                        // ApiKey\\n                        apiKey: [{\\\"required\\\":true,\\\"message\\\":\\\"ApiKey不能为空\\\"},{\\\"min\\\":32,\\\"max\\\":32,\\\"message\\\":\\\"ApiKey长度必须为32-32\\\"}],\\n            },\\n        }\\n    },\\n    watch:{\\n            \\n            //启用ApiKey       \\n            \\\"form.apiKeySwitch\\\":function(nev,old){\\n               if(typeof(nev)==\'string\') {\\n                   this.form.apiKeySwitch = (nev==\'true\');\\n               } else  if(typeof(nev)==\'undefined\') {\\n                    this.form.apiKeySwitch = false;\\n               }        \\n            },\\n    },\\n    components:{\\n    },\\n    computed:{\\n    },\\n    methods: {\\n      \\tlink:function(e,field,binds){\\n      \\t\\tlet that = this;\\n            binds.forEach(function(item){\\n  \\t\\t\\t\\tms.http.post(ms.manager+\'/project/form/link.do\', {id:that.modelId,field:item.field,value:e}).then(function (res) {\\n                    if(res.result && res.data) {\\n                        that.form[ms.util.camelCaseString(item.field)]=res.data[0][item.target];\\n                    }else{\\n                        that.$notify({\\n                            title: \'失败\',\\n                            message: res.msg,\\n                            type: \'warning\'\\n                        });\\n                    }\\n                })\\n\\n            });\\n      \\t},\\n              update: function (row) {\\n                var that = this;\\n                ms.http.post(ms.manager+\\\"/store/apiToken/update.do\\\", row).then(function (data) {\\n                  if (data.result) {\\n                    that.$notify({\\n                      title: \'成功\',\\n                      message: \'更新成功\',\\n                      type: \'success\'\\n                    });\\n\\n                  } else {\\n                    that.$notify({\\n                      title: \'失败\',\\n                      message: data.msg,\\n                      type: \'warning\'\\n                    });\\n                  }\\n                });\\n              },         validate:function(){\\n            var b = false\\n            this.$refs.form.validate(function(valid){\\n                b = valid;\\n            });\\n            return b;\\n        },\\n        getFormData() {\\n            var that = this;\\n            var form = JSON.parse(JSON.stringify(that.form));\\n            form.modelId = that.modelId;\\n            return form;\\n        },\\n        save:function(callback) {\\n            var that = this;\\n            var url = this.formURL.save.url;\\n            if (that.form.id > 0) {\\n                url = this.formURL.update.url;\\n            }\\n            this.$refs.form.validate(function(valid) {\\n                if (valid) {\\n                    var form = JSON.parse(JSON.stringify(that.form));\\n                    form.modelId = that.modelId;\\n                    ms.http.post(url, form).then(function (res) {\\n                        if(callback) {\\n                            callback(res);\\n                        }\\n                    }).catch(function(err){\\n                        callback(err.response.data);\\n                    });\\n                } else{\\n                    callback({\\n                    result:false,msg:\'请检查表单输入项\'\\n                    });\\n                }\\n            })\\n        },\\n        //获取当前APIKey配置\\n        get:function(id) {\\n            var that = this;\\n            that.loading = true;\\n            ms.http.get(this.formURL.get.url, Object.assign({\\\"modelId\\\":that.modelId},this.formURL.get.params)).then(function (res) {\\n                if(res.result&&res.data){\\n                                        that.form = res.data;\\n                    that.loading = false;\\n                } else {\\n                    that.loading = false;\\n                }\\n            }).catch(function (err) {\\n                console.log(err);\\n                that.loading = false;\\n            });\\n        },\\n\\n    },\\n    created:function() {\\n        var that = this;\\n        //渲染create\\n\\t\\tthat.get(); \\n    }\\n});\",\"sql\":\"\\n-- API_TOKEN\\nCREATE TABLE  `{model}API_TOKEN` (\\n    `id` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,\\n    `API_KEY` VARCHAR(255) DEFAULT NULL COMMENT \'ApiKey\',\\n    `API_KEY_SWITCH` VARCHAR(255) DEFAULT NULL COMMENT \'启用ApiKey\',\\n    `LINK_ID` VARCHAR(30) DEFAULT NULL,\\n    `CREATE_DATE` DATETIME DEFAULT NULL COMMENT \'创建时间\',\\n    `CREATE_BY` VARCHAR(50) DEFAULT NULL COMMENT \'创建人\',\\n    `UPDATE_DATE` DATETIME DEFAULT NULL COMMENT \'修改时间\',\\n    `UPDATE_BY` VARCHAR(50) DEFAULT NULL COMMENT \'修改人\',\\n    `DEL` INT(1) DEFAULT 0 COMMENT \'删除标记\',\\n    PRIMARY KEY (`ID`) USING BTREE\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT=\'APIKey配置\';\\n\",\"tableName\":\"API_TOKEN\"}', NULL, 'APIKey配置', 0, '', '[\n    {\n    \"model\":\"apiKey\",\n    \"key\":\"API_KEY\",\n    \"field\":\"API_KEY\",\n    \"javaType\":\"String\",\n    \"jdbcType\":\"VARCHAR\",\n    \"name\":\"ApiKey\",\n    \"type\":\"input\",\n    \"length\":\"255\",\n    \"isShow\":true,\n    \"isNoRepeat\":false,\n    \"isSearch\":false,\n    \"isRequired\":true\n    }\n    ,{\n    \"model\":\"apiKeySwitch\",\n    \"key\":\"API_KEY_SWITCH\",\n    \"field\":\"API_KEY_SWITCH\",\n    \"javaType\":\"Boolean\",\n    \"jdbcType\":\"VARCHAR\",\n    \"name\":\"启用ApiKey\",\n    \"type\":\"switch\",\n    \"length\":\"255\",\n    \"isShow\":false,\n    \"isNoRepeat\":false,\n    \"isSearch\":false,\n    \"isRequired\":false\n    }\n]\n\n', 'config', '2026-04-29 15:25:42', NULL, '2026-03-18 17:25:00', NULL, 0, 1, 'global');

INSERT INTO `mdiy_config` (`id`, `MODEL_ID`, `config_name`, `config_data`, `CONFIG_TYPE`, `update_date`,`update_by`, `create_date`, `create_by`, `del`, `NOT_DEL`, `APP_ID`)VALUES (2, '2034199378837450753', 'APIKey配置', '{\"linkId\":\"0\",\"apiKey\":\"\",\"modelId\":\"2034199378837450753\",\"apiKeySwitch\":false}', 'config', NULL, NULL, NULL, NULL, 0, 0, 'global');

